<?php
namespace App\Http\Controllers;
use App\Models\AiModel; use App\Models\UsageEvent; use App\Models\User; use Illuminate\Http\Request;
class AdminController extends Controller { public function index(){return view('admin.index',['models'=>AiModel::orderBy('name')->get(),'users'=>User::count(),'usage'=>UsageEvent::query()->selectRaw('COUNT(*) as requests, COALESCE(SUM(cost_cents),0) as revenue, COALESCE(SUM(total_tokens),0) as tokens')->first()]);} public function updateModel(Request $r,AiModel $model){$data=$r->validate(['input_price'=>'required|integer|min:0','output_price'=>'required|integer|min:0','is_active'=>'nullable|boolean']);$model->update($data);return back()->with('status','Тариф обновлен.');} public function createModel(Request $r){$data=$r->validate(['name'=>'required|max:80','slug'=>'required|max:120|unique:ai_models,slug','provider'=>'required|max:80','input_price'=>'required|integer|min:0','output_price'=>'required|integer|min:0','context_window'=>'required|integer|min:1']);AiModel::create($data);return back()->with('status','Модель добавлена.');} }
